def preserve_legacy_state(apps, schema_editor):
    """Keep historical completion and attempts valid before new constraints are added."""
    Enrollment = apps.get_model('lms', 'Enrollment')
    Attempt = apps.get_model('lms', 'Attempt')
    Question = apps.get_model('lms', 'Question')
    for enrollment in Enrollment.objects.filter(status='completed'):
        enrollment.completion_source = 'legacy'
        enrollment.save(update_fields=['completion_source'])
    for attempt in Attempt.objects.all().iterator():
        total = sum(Question.objects.filter(exam_id=attempt.exam_id).values_list('points', flat=True))
        attempt.status = 'submitted'
        attempt.started_at = attempt.created_at
        attempt.submitted_at = attempt.created_at
        attempt.auto_score = attempt.score
        attempt.total_points = total
        attempt.percentage = round((float(attempt.score) * 100 / total), 2) if total else 0
        attempt.save(update_fields=['status', 'started_at', 'submitted_at', 'auto_score', 'total_points', 'percentage'])


def reverse_preserve_legacy_state(apps, schema_editor):
    # The added historical fields are deliberately retained if this migration is reversed.
    pass


